import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec4, mix, color, positionLocal, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, BoxGeometry, DirectionalLight, Vector3, Raycaster, Vector2 } = ctx.THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    background: '#0b0b10',
    surface: '#14141a',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    gradientStops: [{ at: 0, hex: '#1b1b23' }, { at: 1, hex: '#101015' }]
  };
  const gStops = colors.gradientStops ?? [{ at: 0, hex: '#1b1b23' }, { at: 1, hex: '#101015' }];
  const topHex = gStops[0].hex;
  const botHex = gStops[gStops.length - 1].hex;
  const accent = colors.accent ?? '#ff2a38';
  const paper = colors.paper ?? '#e8ecf2';
  const inactiveHex = '#a6adba';

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const labels = items.length
    ? items.map((it) => (typeof it === 'string' ? it : (it.text ?? '')).toUpperCase())
    : ['HOME', 'FEATURES', 'COLLECTION', 'PRICING', 'JOURNAL'];

  const root = new Group();
  root.name = 'nav-dock';

  // -------- backdrop stage plane (vertical gradient) --------
  const bgMat = new MeshBasicNodeMaterial();
  {
    const g = uv().y;
    const cTop = color(topHex);
    const cBot = color(botHex);
    bgMat.colorNode = mix(cBot, cTop, g);
  }
  const backdrop = new Mesh(new PlaneGeometry(7, 6), bgMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  // -------- node-local lights --------
  const key = new DirectionalLight(0xffffff, 1.2);
  key.position.set(2.4, 2.8, 3.2);
  root.add(key);
  const rim = new DirectionalLight(0xff2a38, 0.7);
  rim.position.set(-2.6, 1.2, -2.0);
  root.add(rim);

  // -------- machined rail --------
  const railW = 3.6;
  const railH = 0.5;
  const railMat = new MeshStandardNodeMaterial();
  {
    const g = uv().y;
    railMat.colorNode = mix(color(botHex), color(topHex), g);
    railMat.metalness = 0.5;
    railMat.roughness = 0.55;
  }
  const rail = new Mesh(new BoxGeometry(railW, railH, 0.08), railMat);
  rail.position.set(0, 0, 0.15);
  root.add(rail);

  // chamfer specular line hint (thin bright box along top edge)
  const chamferMat = new MeshStandardNodeMaterial();
  chamferMat.colorNode = color('#3a3a44');
  chamferMat.metalness = 0.55;
  chamferMat.roughness = 0.4;
  const chamfer = new Mesh(new BoxGeometry(railW, 0.02, 0.09), chamferMat);
  chamfer.position.set(0, railH / 2 - 0.01, 0.16);
  root.add(chamfer);

  // -------- contact shadow --------
  const shadowMat = new MeshBasicNodeMaterial();
  shadowMat.transparent = true;
  {
    const d = uv().distance(vec3(0.5, 0.5, 0).xy);
    shadowMat.colorNode = color('#000000');
    shadowMat.opacityNode = mix(uniform(0.35), uniform(0.0), d.mul(2.0).clamp(0, 1));
  }
  const shadow = new Mesh(new PlaneGeometry(railW * 1.05, railH * 1.6), shadowMat);
  shadow.position.set(0, -0.06, 0.02);
  root.add(shadow);

  // -------- entries --------
  const spacing = 0.68;
  const startX = -((labels.length - 1) * spacing) / 2;
  const cells = [];
  let activeIndex = 0;

  labels.forEach((label, i) => {
    const cell = new Group();
    const cx = startX + i * spacing;
    cell.position.set(cx, 0, 0.16);
    cell.userData.baseZ = 0.16;

    const isActive = i === activeIndex;
    const txt = ctx.fontAtlas.createText(label, {
      fontSize: 40,
      color: isActive ? paper : inactiveHex,
      align: 'center',
      letterSpacingPx: 3
    });
    txt.scale.setScalar(0.0022);
    txt.position.set(0, 0.02, 0.01);
    cell.add(txt);
    cell.userData.text = txt;
    cell.userData.index = i;

    root.add(cell);
    cells.push(cell);
  });

  // -------- underline bar --------
  const barMat = new MeshStandardNodeMaterial();
  barMat.colorNode = color(accent);
  barMat.emissiveNode = color(accent).mul(1.8);
  barMat.roughness = 0.6;
  barMat.metalness = 0.0;
  const bar = new Mesh(new BoxGeometry(0.28, 0.025, 0.02), barMat);
  const barY = -0.12;
  bar.position.set(startX + activeIndex * spacing, barY, 0.18);
  root.add(bar);

  // -------- entrance --------
  root.position.y = 0.4;
  const timelines = [];
  const introTl = gsap.timeline();
  introTl.fromTo(root.position, { y: 0.4 }, { y: 0.0, duration: 0.7, ease: 'power3.out' });
  introTl.fromTo(rail.scale, { x: 0.96, y: 0.96 }, { x: 1.0, y: 1.0, duration: 0.9, ease: 'power4.out' }, 0);
  timelines.push(introTl);

  // idle breathing
  const idleTl = gsap.timeline({ repeat: -1, yoyo: true });
  idleTl.to(rail.position, { z: 0.17, duration: 3.5, ease: 'sine.inOut' });
  timelines.push(idleTl);

  // -------- interaction --------
  const raycaster = new Raycaster();
  const pointer = new Vector2();
  let hovered = -1;

  function setActive(i) {
    if (i === activeIndex) return;
    const prev = cells[activeIndex];
    const next = cells[i];
    if (prev) {
      const t = ctx.fontAtlas.createText(labels[activeIndex], {
        fontSize: 40, color: inactiveHex, align: 'center', letterSpacingPx: 3
      });
      t.scale.setScalar(0.0022); t.position.copy(prev.userData.text.position);
      prev.remove(prev.userData.text);
      prev.add(t); prev.userData.text = t;
    }
    if (next) {
      const t = ctx.fontAtlas.createText(labels[i], {
        fontSize: 40, color: paper, align: 'center', letterSpacingPx: 3
      });
      t.scale.setScalar(0.0022); t.position.copy(next.userData.text.position);
      next.remove(next.userData.text);
      next.add(t); next.userData.text = t;
    }
    activeIndex = i;
    const targetX = startX + i * spacing;
    gsap.to(bar.position, {
      x: targetX, duration: 0.26, ease: 'back.out(1.4)'
    });
  }

  function pressCell(i) {
    const cell = cells[i];
    if (!cell) return;
    gsap.timeline()
      .to(cell.scale, { x: 0.97, y: 0.97, duration: 0.12, ease: 'back.out(2)' })
      .to(cell.position, { z: cell.userData.baseZ - 0.03, duration: 0.12, ease: 'power2.out' }, 0)
      .to(cell.scale, { x: 1.0, y: 1.0, duration: 0.16, ease: 'power2.out' })
      .to(cell.position, { z: cell.userData.baseZ, duration: 0.16, ease: 'power2.out' }, '<');
  }

  root.userData.handlers = {
    onPointerMove(ev, camera) {
      if (!camera) return;
      pointer.set(ev.ndcX ?? 0, ev.ndcY ?? 0);
      raycaster.setFromCamera(pointer, camera);
      const hits = raycaster.intersectObjects(cells.map((c) => c.children).flat(), true);
      let found = -1;
      if (hits.length) {
        let o = hits[0].object;
        while (o && o.parent && o.userData.index === undefined) o = o.parent;
        if (o && o.userData.index !== undefined) found = o.userData.index;
      }
      if (found !== hovered) {
        hovered = found;
      }
    },
    onClick(ev, camera) {
      if (!camera) return;
      pointer.set(ev.ndcX ?? 0, ev.ndcY ?? 0);
      raycaster.setFromCamera(pointer, camera);
      const hits = raycaster.intersectObjects(cells, true);
      if (hits.length) {
        let o = hits[0].object;
        while (o && o.parent && o.userData.index === undefined) o = o.parent;
        if (o && o.userData.index !== undefined) {
          const i = o.userData.index;
          pressCell(i);
          setActive(i);
          const map = ['hub-features', 'hub-collection', 'hub-pricing', 'hub-journal'];
          if (i > 0) ctx.emit('navigate', { to: map[i - 1] });
          else ctx.emit('navigate', { to: 'hub-home' });
        }
      }
    }
  };

  root.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    gsap.killTweensOf(bar.position);
    root.traverse((o) => {
      if (o.geometry) o.geometry.dispose?.();
      if (o.material) {
        if (Array.isArray(o.material)) o.material.forEach((m) => m.dispose?.());
        else o.material.dispose?.();
      }
    });
  };

  return root;
}
